// === pengguna.json ===
[{ "nama": "Rina", "umur": 21 }, { "nama": "Budi", "umur": 30 }]
// === main.js ===
import { readFile, writeFile } from 'node:fs/promises';
const data = JSON.parse(await readFile('pengguna.json', 'utf8'));
data.push({ nama: 'Dodi', umur: 25 });
await writeFile('pengguna.json', JSON.stringify(data, null, 2));
const lagi = JSON.parse(await readFile('pengguna.json', 'utf8'));
console.log(lagi.map((p) => p.nama).join(', '));
